 let id=Number(st.active||0);if(id===Number(me)){if(st.soloNPC)st.soloNPC.waitingForHuman={playerId:Number(me),turn:Number(st.turn||1),phase:String(st.phase||'UNTAP')};clearTimeout(soloNpcTimer);soloNpcTimer=null;return}
 if(!soloNpcPlayer(id))return;if(st.soloNPC)st.soloNPC.waitingForHuman=null;
