function closeDeckVaultDrawer(){if(!vaultDrawerOpen)return;deckVaultSetAmbience(null);let drawer=document.querySelector('.deckVaultPremiumDetail'),reduced=!!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;if(drawer&&!reduced){drawer.classList.remove('opening');drawer.classList.add('closing');setTimeout(()=>{vaultDrawerOpen=false;vaultDrawerOpening=false;vaultPanelMode='actions';renderDeckVault({preserveScroll:true})},180)}else{vaultDrawerOpen=false;vaultDrawerOpening=false;vaultPanelMode='actions';renderDeckVault({preserveScroll:true})}}
function renderDeckVault({preserveScroll=false}={}){if(!playerProfile)return;let decks=playerProfile.decks||[];if(!decks.some(d=>d.id===vaultSelectedDeckId))vaultSelectedDeckId=(activeDeckId&&decks.some(d=>d.id===activeDeckId)?activeDeckId:decks[0]?.id)||null;let selected=decks.find(d=>d.id===vaultSelectedDeckId)||null,ambient=vaultDrawerOpen&&selected?deckVaultPalette(selected):null,root=$('choices'),savedScroll=preserveScroll?(window.scrollY||document.documentElement.scrollTop||0):0;if(!root)return;root.innerHTML='<div class="deckVaultPremiumExperience"><header class="deckVaultPremiumHeader"><button class="deckVaultPremiumBack" type="button" data-vault-close aria-label="Back to Battle Lobby">Back</button><button class="deckVaultPremiumAdd" type="button" data-vault-new aria-label="Add Verified Deck">Add Verified Deck</button></header>'+deckVaultRowsHtml(decks)+(vaultDrawerOpen&&selected?deckVaultDetailHtml(selected):'')+'</div>';if(preserveScroll)requestAnimationFrame(()=>window.scrollTo(0,savedScroll));deckVaultSetAmbience(ambient);let back=root.querySelector('[data-vault-close]');if(back)back.onclick=closeDeckVault;root.querySelectorAll('[data-vault-deck]').forEach(b=>b.onclick=()=>{let id=b.dataset.vaultDeck;if(vaultDrawerOpen&&String(vaultSelectedDeckId)===String(id))return closeDeckVaultDrawer();vaultSelectedDeckId=id;vaultPanelMode='actions';vaultDrawerOpen=true;vaultDrawerOpening=true;renderDeckVault({preserveScroll:true});vaultDrawerOpening=false});let drawerClose=root.querySelector('[data-vault-drawer-close]');if(drawerClose)drawerClose.onclick=closeDeckVaultDrawer;let add=root.querySelector('[data-vault-new]');if(add)add.onclick=beginNewDeckFromVault;root.querySelectorAll('[data-vault-cmd]').forEach(b=>b.onclick=()=>handleDeckVaultCommand(b.dataset.vaultCmd));let rename=$('vaultRenameInput');if(rename)rename.addEventListener('keydown',e=>{if(e.key==='Enter')handleDeckVaultCommand('save-rename')})}
