function chooseFaceDownCast(){let cards=(prof.cards||[]).map(c=>({card:c,mechs:faceDownCardMechanisms(c)})).filter(x=>x.mechs.length);if(!cards.length)return toast('No Morph, Megamorph, or Disguise cards are loaded in this deck.');choice(cards.map((x,i)=>(i+1)+' · '+x.card.n+' · '+x.mechs.map(m=>m.toUpperCase()).join('/')),pick=>{let x=cards[parseInt(pick,10)-1];if(!x)return;let chooseMech=cb=>x.mechs.length===1?cb(x.mechs[0]):choice(x.mechs.map(m=>m.toUpperCase()),m=>cb(String(m).toLowerCase()));chooseMech(mech=>{let ref=storeFaceDownPrivate(x.card,mech),pub=MTGFaceDownMechanics.castPublicCard(mech);cmd('cast',{n:pub.n,cardPublic:pub,faceDownState:{mechanism:mech,privateIdentityRef:ref,origin:'cast-face-down',castFaceDown:true},fromZone:'hand'})})})}
function chooseManifestOrCloak(){let cards=prof.cards||[];if(!cards.length)return toast('Load a deck first so the hidden card can stay private on this device.');choice(['Manifest a card','Cloak a card'],kind=>{let mech=kind.startsWith('Cloak')?'cloak':'manifest';choice(cards.map((c,i)=>(i+1)+' · '+c.n),pick=>{let card=cards[parseInt(pick,10)-1];if(!card)return;let ref=storeFaceDownPrivate(card,mech),oid='fd_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8);cmd('faceDownEnter',{objectId:oid,mechanism:mech,privateIdentityRef:ref,origin:mech})})})}
