function handleAssistAction(action,item){wakePlayerHud(30000);if(item?.key)markAssistSeen(item.key);if(action==='replacement-order')return showReplacementOrderPrompt();if(action==='oracle-choice')return showOracleChoicePrompt();if(action==='order-triggers')return showTriggerOrderPrompt();if(action==='review-stack')return inspectStackQuick(item?.reference?.type==='stack'?item.reference.id:null);if(action==='open-battlefield')return setPlayerHudPage('battlefield');if(action==='open-quick-actions')return quickActionMenu();if(action==='open-controls'){setPlayerHudPage('home');return toast('Assist controls ready.')}}
