function eventLabel(e){let p=e.payload||{};if(e.type==='PHASE106_BUYBACK_RESOLVED')return 'Buyback · returned to hand';if(e.type==='ADVENTURE_RESOLVED_TO_EXILE')return 'Adventure resolved · exile permission';if(e.type==='CAST_PERMISSION_GRANTED')return 'Cast permission · granted';if(e.type==='CAST_PERMISSION_REVOKED')return 'Cast permission · revoked';if(e.type==='TRACKED_CAST_NONPERMANENT_RESOLVED')return 'Tracked spell · resolved destination';if(e.type==='FACE_DOWN_PERMANENT_ENTERED')return String(p.mechanism||'FACE DOWN').toUpperCase()+' · entered face down';if(e.type==='PERMANENT_FACE_UP_SPECIAL_ACTION')return 'Turned face up · special action';if(e.type==='LINK_GROUP_CREATED')return 'Linked ability · group created';if(e.type==='LINK_CHOICE_RECORDED')return 'Linked choice · '+String(p.key||'choice');if(e.type==='LINK_EXILED_OBJECTS_RECORDED')return 'Linked exile · '+((p.objectIds||[]).length)+' object(s)';if(e.type==='LINK_COST_RECORDED')return 'Linked cost · '+String(p.key||'cost');if(e.type==='LIFE_CHANGED'||e.type==='LIFE_CHANGED_EXACT')return 'P'+p.playerId+' life '+(String(p.delta).startsWith('-')?'':'+')+p.delta;if(e.type==='DAMAGE_DEALT')return p.amount+(p.isCommander?' commander':'')+' damage to P'+p.defenderId;if(e.type==='COMMANDER_DAMAGE_DEALT')return p.amount+' commander damage to P'+p.defenderId;if(e.type==='COUNTER_CHANGED')return 'P'+p.playerId+' '+p.counter+' '+(p.delta>=0?'+':'')+p.delta;if(e.type==='TOKEN_COHORT_CREATED')return 'Tokens ×'+(p.cohort?.q||p.quantity||1);if(e.type==='STACK_TRIGGER_GROUP_ADDED')return 'Triggers ×'+(p.item?.count||p.count||1)+' · '+(p.item?.name||'group');if(e.type==='STACK_ITEM_ADDED')return 'Stack + '+(p.item?.name||'item');if(e.type==='STACK_ITEM_REMOVED')return p.reason==='countered'?'Countered · stack object':p.reason==='all-targets-illegal'?'Did not resolve · illegal targets':p.reason==='exiled'?'Stack object exiled':p.reason==='resolved'?'Stack object resolved':'Stack item removed';if(e.type==='SMART_PRIORITY_MODE_SET')return 'Smart Priority · '+String(p.mode||'standard').toUpperCase();if(e.type==='SMART_PRIORITY_STOPS_SET')return 'P'+(p.playerId||e.actorId)+' priority stops · '+(typeof MTGSmartPriority!=='undefined'?MTGSmartPriority.stopLabel(p.stops):'UPDATED');if(e.type==='PRIORITY_WINDOW_OPENED')return 'Priority opened · P'+(p.flow?.holder||'—');if(e.type==='PRIORITY_PASSED')return 'P'+(p.playerId||e.actorId)+' passed priority'+(p.allPassed?' · all passed':'');if(e.type==='PRIORITY_CLAIMED')return p.holdOnly?'P'+e.actorId+' declared response':'P'+e.actorId+' claimed casual response';if(e.type==='PRIORITY_WINDOW_CLOSED')return 'Priority window closed';return e.type.replaceAll('_',' ')}
